package main

import (
	"context"

	userpb "example.com/user"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

type server struct {
	userpb.UnimplementedUserServiceServer // forward-compatible default
	users map[string]string             // id -> name (demo store)
}

func (s *server) GetUser(ctx context.Context, req *userpb.GetUserRequest) (*userpb.User, error) {
	name, ok := s.users[req.GetId()]
	if !ok {
		// Return a STATUS-CODED error, not a plain Go error.
		return nil, status.Errorf(codes.NotFound, "user %q not found", req.GetId())
	}
	return &userpb.User{Id: req.GetId(), Name: name}, nil
}

