package solution

import (
	"context"

	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

// LoggingRecovery is a unary interceptor: it wraps every RPC, turning a
// panic into a clean codes.Internal error instead of crashing the server.
func LoggingRecovery(ctx context.Context, req any, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (resp any, err error) {
	defer func() {
		if r := recover(); r != nil {
			// Named return values let us set err from inside the defer.
			err = status.Errorf(codes.Internal, "panic in %s: %v", info.FullMethod, r)
			resp = nil
		}
	}()
	return handler(ctx, req) // delegate to the actual RPC handler
}

// Wire it up with: grpc.NewServer(grpc.UnaryInterceptor(LoggingRecovery))

