package solution

import (
	"context"
	"testing"

	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

func TestRecover(t *testing.T) {
	info := &grpc.UnaryServerInfo{FullMethod: "/svc/Method"}
	panicker := func(ctx context.Context, req any) (any, error) { panic("boom") }
	_, err := LoggingRecovery(context.Background(), nil, info, panicker)
	if status.Code(err) != codes.Internal {
		t.Fatalf("want Internal, got %v", status.Code(err))
	}
}

func TestPassThrough(t *testing.T) {
	info := &grpc.UnaryServerInfo{FullMethod: "/svc/Method"}
	ok := func(ctx context.Context, req any) (any, error) { return "ok", nil }
	resp, err := LoggingRecovery(context.Background(), nil, info, ok)
	if err != nil || resp != "ok" {
		t.Fatalf("want ok/nil, got %v/%v", resp, err)
	}
}

