func (s *server) ListUsers(req *pb.Query, stream pb.UserService_ListUsersServer) error {
	ctx := stream.Context() // carries the client's deadline/cancellation
	for _, u := range s.match(req) {
		select {
		case <-ctx.Done():
			// Client gave up or deadline hit: stop and report it.
			return status.FromContextError(ctx.Err()).Err()
		default:
		}
		if err := stream.Send(u); err != nil { // one response per item
			return err // transport error; stop streaming
		}
	}
	return nil // nil = clean end of stream; client receives io.EOF
}
